use std::collections::HashSet;

verus! {

/// Return a new vector with duplicates removed.
/// - The result contains no duplicates.
/// - The set of elements in the result equals the set of elements in the input.
/// Order is preserved (first occurrence kept).
pub fn remove_duplicates(nums: Vec<i32>) -> (res: Vec<i32>)
    ensures
        // no duplicates in the result
        forall |i: int, j: int|
            0 <= i && i < j && j < res.len() ==> res[i] != res[j],
        // same set of elements as input
        res@.to_set() == nums@.to_set(),
        // order preserved: result is a subsequence of input
        res@.is_subsequence_of(nums@),
{
    let mut seen: HashSet<i32> = HashSet::new();
    let mut res: Vec<i32> = Vec::new();

    for x in nums
        invariant
            // seen matches the set of elements currently in res
            res@.to_set() == seen@,
            // res has no duplicates so far
            forall |i: int, j: int|
                0 <= i && i < j && j < res.len() ==> res[i] != res[j],
    {
        if seen.insert(x) {
            res.push(x);

            // Help Verus connect the push and the set update.
            assert(res@.to_set() == seen@);
            // Pushing only when x was not already present preserves uniqueness.
            assert(forall |i: int, j: int|
                0 <= i && i < j && j < res.len() ==> res[i] != res[j]);
        } else {
            // seen (and thus res@.to_set()) unchanged
            assert(res@.to_set() == seen@);
        }
    }
    res
}

} // verus!